"use client";
// Interface language (English or Hindi). The English text is the key: `t("Review facts")` returns the Hindi for it when the
// language is Hindi and a translation exists, and the English otherwise, so a string with no translation never shows blank.
// The Hindi table (hi.json) is generated by scripts/translate_ui_hi.py from the strings `scripts/extract-ui-strings.ts` finds;
// nothing in it is edited by hand. Only interface text is translated: the case's own text (facts, grounds, quotes) is not.
import { createContext, useCallback, useContext, useEffect, useMemo, useState, type ReactElement, type ReactNode } from "react";
import hi from "./hi.json";

export type Lang = "en" | "hi";
const STORAGE_KEY = "vs-lang";
const HI = hi as Record<string, string>;

/** The Hindi for an English interface string, or the string itself when there is none. */
export function translate(text: string, lang: Lang): string {
  return lang === "hi" ? (HI[text] ?? text) : text;
}

interface I18nValue {
  lang: Lang;
  setLang: (lang: Lang) => void;
  t: (text: string) => string;
}

const I18nContext = createContext<I18nValue>({ lang: "en", setLang: () => {}, t: (text) => text });

export function I18nProvider({ children }: { children: ReactNode }): ReactElement {
  const [lang, setLangState] = useState<Lang>("en");

  // Read the saved choice after mount, so the first render matches the server's English.
  useEffect(() => {
    try {
      if (window.localStorage.getItem(STORAGE_KEY) === "hi") setLangState("hi");
    } catch {
      /* storage blocked: stay in English */
    }
  }, []);

  useEffect(() => {
    document.documentElement.lang = lang;
  }, [lang]);

  const setLang = useCallback((next: Lang) => {
    setLangState(next);
    try {
      window.localStorage.setItem(STORAGE_KEY, next);
    } catch {
      /* the choice then lasts for this visit only */
    }
  }, []);

  const value = useMemo<I18nValue>(() => ({ lang, setLang, t: (text) => translate(text, lang) }), [lang, setLang]);
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

/** Like `t`, for a prop that may hold a string or other content: only a string is translated. */
export function useTx(): (node: ReactNode) => ReactNode {
  const t = useContext(I18nContext).t;
  return (node) => (typeof node === "string" ? t(node) : node);
}

/** `t(english)` for the current language. Outside a provider it returns the English unchanged. */
export function useT(): (text: string) => string {
  return useContext(I18nContext).t;
}

export function useLang(): { lang: Lang; setLang: (lang: Lang) => void } {
  const { lang, setLang } = useContext(I18nContext);
  return { lang, setLang };
}
